  ('{"kanji":"正","meanings":["correct","right"],"kunyomi":["ただ.しい","まさ"],"onyomi":["せい","しょう"],"card_type":"kanji_flashcard","examples":[{"word":"正しい","reading":"ただしい","meaning":"correct, right","red":true},{"word":"正確","reading":"せいかく","meaning":"correct","red":true},{"word":"お正月","reading":"おしょうがつ","meaning":"the New Year","red":true},{"word":"正直","reading":"しょうじき","meaning":"honest"}]}'),
