  ('{"kanji":"登","meanings":["to climb"],"kunyomi":["のぼ.る"],"onyomi":["とう","と"],"card_type":"kanji_flashcard","examples":[{"word":"登る","reading":"のぼる","meaning":"to ascend, to climb","red":true},{"word":"登録する","reading":"とうろくする","meaning":"to register","red":true},{"word":"登山","reading":"とざん","meaning":"mountain climbing"}]}'),
