  ('{"kanji":"降","meanings":["to descend","to fall (rain)"],"kunyomi":["お.りる","お.ろす","ふ.る"],"onyomi":["こう"],"card_type":"kanji_flashcard","examples":[{"word":"雨が降る","reading":"あめがふる","meaning":"to fall (rain, snow)","red":true},{"word":"降りる","reading":"おりる","meaning":"to get off","red":true},{"word":"降ろす","reading":"おろす","meaning":"to drop off, to unload"},{"word":"降車口","reading":"こうしゃぐち","meaning":"exit","red":true},{"word":"降雨量","reading":"こううりょう","meaning":"rainfall"}]}'),
